/* Responsive photo (AVIF + WebP, lazy) or a labelled placeholder slot when
 * the real photo hasn't been added yet. Photos are generated by
 * `npm run images` (see scripts/optimize-images.mjs). */

import photos from '../content/photos.generated.js';
import { esc } from './utils.js';

export function photo({ name, alt, t, cls = '', sizes = '(min-width: 900px) 50vw, 100vw', eager = false }) {
  const p = name && photos[name];
  if (!p) {
    return `
<figure class="photo-slot ${cls}" role="img" aria-label="${esc(alt)}">
  <span class="photo-slot__label mono">${esc(t.photoPlaceholder)}</span>
  <span class="photo-slot__corner" aria-hidden="true"></span>
</figure>`;
  }
  const set = (fmt) => p.widths.map((w) => `/img/${name}-${w}.${fmt} ${w}w`).join(', ');
  const largest = p.widths[p.widths.length - 1];
  return `
<picture class="photo ${cls}">
  <source type="image/avif" srcset="${set('avif')}" sizes="${sizes}">
  <source type="image/webp" srcset="${set('webp')}" sizes="${sizes}">
  <img src="/img/${name}-${largest}.webp" alt="${esc(alt)}" width="${p.width}" height="${p.height}" loading="${eager ? 'eager' : 'lazy'}" decoding="async">
</picture>`;
}
